//Code74k.ts

type Code74kEntry = {
  id: string;
  conversations: Code74kConversation[];
};

type Code74kConversation = {
  from: "human" | "gpt";
  value: string;
};

type Code74kData = Code74kEntry[];

type Code74kUtil = {
  data: Code74kData;
  getEntry: (id: string) => Code74kEntry | undefined;
  getConversation: (
    id: string,
    conversationIndex: number
  ) => Code74kConversation | undefined;
};

const code74kData: Code74kData = /*Data from Code74k.json*/;

const code74kUtil: Code74kUtil = {
  data: code74kData,
  getEntry: (id: string) => code74kData.find((entry) => entry.id === id),
  getConversation: (id: string, index: number) => {
    const entry = code74kUtil.getEntry(id);
    return entry?.conversations[index];
  },
};

export default code74kUtil;
